-- Services copy: answer-first citability rewrite (description + deliverables + process).
-- MERGE-only via jsonb '||': startingAt, outcome, tagline, seo, name, icon are left
-- at their live values. Idempotent — re-running just re-applies the same three keys.
-- Manual: run in the prod Supabase SQL editor (services are DB-driven, not from code).

update public.services set data = data || '{"description":"SEO & Organic Growth is the work of earning durable search visibility by building content as infrastructure, not chasing keywords one at a time. I build three compounding layers: topic clusters that establish authority on a subject, programmatic pages that scale coverage across a repeatable pattern, and an answer-first content system written to be cited by Google and by LLMs like ChatGPT and Perplexity.","deliverables":["A technical SEO audit that returns a prioritised plan for the issues blocking your indexing and rankings.","A topic-cluster architecture — one pillar page plus interlinked supporting articles — that reads to search engines as subject authority.","A programmatic SEO build-out wherever a repeatable page pattern (location, template, or comparison pages) can rank at scale.","Schema markup, internal linking, and GEO optimisation so Google and AI answer engines can parse and cite your pages."],"process":[{"step":"Audit","detail":"A 30-day technical and content crawl that produces a prioritised list of what''s broken and what''s winnable."},{"step":"Architect","detail":"Design the topic clusters and the programmatic layer around the queries worth owning."},{"step":"Build","detail":"Ship the pillar pages, supporting articles, and programmatic templates, with schema and internal links in place."},{"step":"Compound","detail":"Refresh, expand, and instrument on a monthly cadence so the system keeps gaining ground."}]}'::jsonb where slug = 'seo';
update public.services set data = data || '{"description":"Performance Marketing is paid acquisition on Google and Meta, run as a tunable system rather than a monthly spend you hope works. I restructure the ad account around buyer intent, stand up a creative-testing pipeline, and rebuild the post-click landing pages — so every rupee of spend is measured against profit, not just clicks.","deliverables":["An account restructure that groups campaigns by buyer-intent tier, so budget follows the traffic most likely to convert.","A creative-testing system with a fixed weekly production cadence, so fresh ads ship on schedule instead of in scrambles.","Landing-page rebuilds for message-match and load speed — the two biggest post-click conversion levers.","A pragmatic attribution setup your team can actually trust when deciding where spend goes."],"process":[{"step":"Diagnose","detail":"Find the real bottleneck — usually the post-click experience, not the ad."},{"step":"Restructure","detail":"Rebuild the account around intent tiers and a clean testing matrix."},{"step":"Systematise","detail":"Turn creative into a weekly pipeline with a defined testing cadence."},{"step":"Scale","detail":"Increase spend only on the segments where the unit economics hold."}]}'::jsonb where slug = 'performance';
update public.services set data = data || '{"description":"Content Strategy is the system that turns one serious idea into a month of distribution. I set editorial pillars tied to business outcomes, build a repurposing pipeline that splits each flagship piece into around twenty channel-ready assets, and enforce a QA rubric so nothing thin ships under your name.","deliverables":["An editorial strategy with content pillars mapped to business outcomes, not just topics.","A repurposing pipeline that turns one flagship piece into roughly twenty channel-specific assets.","An editorial QA rubric and brand-voice guide that keep quality and tone consistent across writers.","A distribution calendar that schedules each asset across your owned channels."],"process":[{"step":"Strategy","detail":"Define content pillars tied to revenue, not traffic vanity metrics."},{"step":"System","detail":"Stand up the production and QA pipeline your team will run."},{"step":"Distribute","detail":"Repurpose each idea and place it across every owned surface."},{"step":"Review","detail":"Cut what underperforms each month and double down on what works."}]}'::jsonb where slug = 'content';
update public.services set data = data || '{"description":"AI Automation is the work of wiring AI into the specific tasks where it adds leverage — research, drafting, analysis, and operations — while keeping human judgement in the loop. I map your highest-leverage workflows, build them with quality gates so accuracy holds as volume grows, and hand your team a documented system they can run without me.","deliverables":["A workflow audit and automation roadmap that ranks tasks by leverage and risk.","Prompt libraries grounded in your brand voice and your own data, not generic templates.","Human-in-the-loop pipelines with QA gates that catch errors before they ship.","Team enablement and documentation so the system outlives the engagement."],"process":[{"step":"Map","detail":"Identify the highest-leverage, lowest-risk tasks to automate first."},{"step":"Build","detail":"Wire each workflow with explicit quality gates."},{"step":"Validate","detail":"Prove output quality holds before scaling volume."},{"step":"Enable","detail":"Document and hand over a system the team can operate."}]}'::jsonb where slug = 'ai-workflows';
update public.services set data = data || '{"description":"Startup Advisory is hands-on, founder-to-founder guidance for early and growth-stage founders. Across bi-weekly working sessions we pick the one growth lever that matters this quarter — distribution, positioning, or the unglamorous systems that compound — and work it together, with async access between sessions for fast decisions.","deliverables":["Bi-weekly working sessions focused on the current quarter''s single biggest lever.","A growth and distribution strategy built around how your product actually reaches people.","A positioning and messaging review that sharpens how the market understands you.","Async access between sessions, so decisions don''t wait two weeks."],"process":[{"step":"Context","detail":"Understand the business and its real constraints before advising."},{"step":"Focus","detail":"Identify the one lever that matters most this quarter."},{"step":"Execute","detail":"Work that lever together, week over week."},{"step":"Compound","detail":"Build the system so the gains outlast the engagement."}]}'::jsonb where slug = 'advisory';
update public.services set data = data || '{"description":"Speaking & Workshops are practical sessions on SEO, AI workflows, and founder-led growth, built on real experiments and outcomes rather than recycled theory. Each keynote or workshop is tailored to the audience and sends the room home with frameworks and templates they can apply on Monday.","deliverables":["A keynote or workshop tailored to your audience and the outcome you want.","Practical frameworks and takeaway templates the room keeps after the session.","A live Q&A plus follow-up resources for attendees.","Optional recording and repurposing rights for your team."],"process":[{"step":"Brief","detail":"Understand the audience and the outcome the session must deliver."},{"step":"Craft","detail":"Build the session around real, first-hand receipts."},{"step":"Deliver","detail":"Engage the room and leave them with usable systems."},{"step":"Extend","detail":"Provide resources and templates that outlast the talk."}]}'::jsonb where slug = 'speaking';
